// What a writer reads before writing — the concept card on the Draft stage and
// the facts the Gemini lane drafts from.
//
// Both JSON files are generated by scripts/social-concepts.mjs from the
// hogwarts SPOTLIGHT.md files and the brand pages' Voice sections. Import it
// from server code only (actions, the draft lane): concepts.json is ~150KB and
// a client needs one feature's note at a time, which readConcept serves. No
// `server-only` import, because vitest loads the draft lane that reads this.

import conceptsData from "../../content/social/concepts.json";
import voiceData from "../../content/social/voice.json";
import { findSlot, type PlanSlot } from "@/components/root/social/plan";

export interface Concept {
  feature: string;
  title: string;
  personas: string[];
  oneLine: string;
  without: string;
  what: string;
  who: string;
  say: string;
  dontSay: string;
  angles: string;
}

type ConceptBody = Omit<Concept, "feature">;

/** Brands whose features are the school SaaS — Balqalam is its Arabic face. */
const SCHOOL_BRANDS = new Set(["hogwarts", "balqalam"]);

/**
 * features.json and plan.json name a few features by the word a post would
 * use; the SPOTLIGHT directory is named for the code. Map the strays.
 */
const ALIASES: Record<string, string> = {
  fees: "my-fees",
  gradebook: "grades",
  parents: "parent",
  teachers: "teacher",
  payment: "billing",
};

export function conceptFor(
  brand: string,
  feature: string | null | undefined,
): Concept | null {
  if (!feature || !SCHOOL_BRANDS.has(brand)) return null;
  const school = (conceptsData as { school: Record<string, ConceptBody> })
    .school;
  const id = school[feature] ? feature : ALIASES[feature];
  const body = id ? school[id] : undefined;
  return body ? { feature: id, ...body } : null;
}

export function voiceFor(brand: string): string | undefined {
  const v = (voiceData as Record<string, string>)[brand];
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}

function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max).trimEnd()}…` : text;
}

/**
 * The prompt's "what the post is about" section: the slot's direction first
 * (it is the narrower instruction), then the feature's facts and its
 * do-not-say list. Capped so one rich SPOTLIGHT cannot crowd out the brief.
 */
export function conceptPromptNote(
  brand: string,
  feature?: string,
  slotKey?: string,
): string | undefined {
  const slot: PlanSlot | null = slotKey ? findSlot(slotKey) : null;
  const concept = conceptFor(brand, feature ?? slot?.feature);
  const lines: string[] = [];
  if (slot) {
    lines.push(
      `Calendar slot ${slot.key} — theme: ${slot.theme}; kind: ${slot.kind}; speaks to: ${slot.persona}.`,
      `Angle: ${slot.angle}`,
      `Shape: ${slot.slotGuide}`,
    );
  }
  if (concept) {
    lines.push(
      `Feature: ${concept.title}`,
      `In one line: ${concept.oneLine}`,
      `What happens: ${clip(concept.what, 1400)}`,
    );
    if (concept.say) lines.push(`You can say: ${clip(concept.say, 700)}`);
    if (concept.dontSay)
      lines.push(`Do not say: ${clip(concept.dontSay, 600)}`);
  }
  return lines.length ? lines.join("\n") : undefined;
}
